class Gradebook:
    def __init__(self) -> None:
        """
        Initializes the gradebook.

        Attributes:
        assignments (dict): A dictionary to store assignment information.
        grades (dict): A dictionary to store grades for each student.
        """
        self.assignments = {}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """
        Adds an assignment to the gradebook.

        Args:
        name (str): The name of the assignment.
        weight (float): The weight of the assignment.
        kind (str): The type of the assignment (default is "homework").
        """
        self.assignments[name] = {"weight": weight, "kind": kind}
        for student in self.grades:
            self.grades[student][name] = None

    def record(self, student: str, assignment: str, grade: float) -> None:
        """
        Records a grade for a student in the gradebook.

        Args:
        student (str): The name of the student.
        assignment (str): The name of the assignment.
        grade (float): The grade of the student.

        Raises:
        ValueError: If the grade is outside the scale 2.0 to 5.0.
        """
        if not 2.0 <= grade <= 5.0:
            raise ValueError("Grade must be between 2.0 and 5.0")

        if student not in self.grades:
            self.grades[student] = {}

        if assignment not in self.assignments:
            raise ValueError("Assignment does not exist")

        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        """
        Calculates the weighted average of a student.

        Args:
        student (str): The name of the student.

        Returns:
        float: The weighted average of the student, rounded to two decimal places.
        """
        if student not in self.grades:
            return 0.0

        total_weight = sum(assignment["weight"] for assignment in self.assignments.values())
        weighted_sum = 0.0

        for assignment, grade in self.grades[student].items():
            weight = self.assignments[assignment]["weight"]
            if grade is None:
                weighted_sum += weight * 2.0
            else:
                weighted_sum += weight * grade

        return round(weighted_sum / total_weight, 2)
